window.RTLBenchLSData.register("assets/d31661371b436e542c82296e42a135ce40bbc6421fe948f8d7b5a1ded6acc829.txt","module autovcoder_029073 (\n    Rb,\n    Reset,\n    CLK,\n    Sum,\n    Roll,\n    Win,\n    Lose\n);\n  input Rb;\n  input Reset;\n  input CLK;\n  input [3:0] Sum;\n  output Roll;\n  output Win;\n  output Lose;\n  reg Roll;\n  reg Win;\n  reg Lose;\n\n  reg [2:0] State;\n  reg [2:0] Nextstate;\n  reg [3:0] Point;\n  reg Sp;\n  initial begin\n    State = 0;\n    Nextstate = 0;\n    Point = 2;\n  end\n  always @(Rb or Reset or Sum or State) begin\n    Sp = 1'b0;\n    Roll = 1'b0;\n    Win = 1'b0;\n    Lose = 1'b0;\n    Nextstate = 0;\n    case (State)\n      0: begin\n        if (Rb == 1'b1) begin\n          Nextstate = 1;\n        end\n      end\n      1: begin\n        if (Rb == 1'b1) begin\n          Roll = 1'b1;\n        end else if (Sum == 7 | Sum == 11) begin\n          Nextstate = 2;\n        end else if (Sum == 2 | Sum == 3 | Sum == 12) begin\n          Nextstate = 3;\n        end else begin\n          Sp = 1'b1;\n          Nextstate = 4;\n        end\n      end\n      2: begin\n        Win = 1'b1;\n        if (Reset == 1'b1) begin\n          Nextstate = 0;\n        end\n      end\n      3: begin\n        Lose = 1'b1;\n        if (Reset == 1'b1) begin\n          Nextstate = 0;\n        end\n      end\n      4: begin\n        if (Rb == 1'b1) begin\n          Nextstate = 5;\n        end\n      end\n      5: begin\n        if (Rb == 1'b1) begin\n          Roll = 1'b1;\n        end else if (Sum == Point) begin\n          Nextstate = 2;\n        end else if (Sum == 7) begin\n          Nextstate = 3;\n        end else begin\n          Nextstate = 4;\n        end\n      end\n      default: begin\n        Nextstate = 0;\n\n      end\n    endcase\n  end\n  always @(posedge CLK) begin\n    State <= Nextstate;\n    if (Sp == 1'b1) begin\n      Point <= Sum;\n    end\n  end\nendmodule\n\n");
